'use strict';

/*
 * Builds the standalone JSON Schema validators the on-device engine uses (ML-27/ML-28, plan sections 6.1 and 6.6).
 * The sanitized OCR payload schema and the Contract A, B and C schemas (docs/schemas) are compiled with Ajv (draft 2020-12,
 * all errors, formats from ajv-formats) into one CommonJS module, src/engine/contracts/validators.generated.js,
 * so the app never compiles a schema at run time (no eval, no new Function). A small .d.ts is written beside it.
 *
 *   node scripts/build-validators.js            write the two generated files
 *   node scripts/build-validators.js --check    exit 1 when they are stale, else print "up to date"
 *
 * --check regenerates in memory and compares with the files on disk with line endings normalized (decision D14).
 * It never prints file contents.
 */

const fs = require('fs');
const path = require('path');
const Ajv2020 = require('ajv/dist/2020').default;
const { _ } = require('ajv');
const standaloneCode = require('ajv/dist/standalone').default;
const addFormats = require('ajv-formats');

const SCHEMA_DIR = path.join(__dirname, '..', '..', 'docs', 'schemas');
const OUT_DIR = path.join(__dirname, '..', 'src', 'engine', 'contracts');

// [export name, schema file below docs/schemas]
const SCHEMAS = [
  ['validatePayload', 'ocr_payload_contract.json'],
  ['validateA', 'parsing_contract_template.json'],
  ['validateB', 'scoring_output_contract.json'],
  ['validateC', 'llm_phrasing_contract.json'],
];

const DECLARATIONS = [
  '// Generated by scripts/build-validators.js (ML-27/ML-28). Do not edit; run `npm run engine:validators`.',
  '',
  '/** One Ajv error object (the fields the engine reads). */',
  'export interface SchemaError {',
  '  instancePath: string;',
  '  schemaPath: string;',
  '  keyword: string;',
  '  params: { [key: string]: unknown };',
  '  message?: string;',
  '}',
  '',
  'export interface SchemaValidator {',
  '  (data: unknown): boolean;',
  '  errors?: SchemaError[] | null;',
  '}',
  '',
  'export const validatePayload: SchemaValidator;',
  'export const validateA: SchemaValidator;',
  'export const validateB: SchemaValidator;',
  'export const validateC: SchemaValidator;',
  '',
].join('\n');

function normalizeText(raw) {
  return raw.replace(/^\uFEFF/, '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

function readSchema(name) {
  return JSON.parse(normalizeText(fs.readFileSync(path.join(SCHEMA_DIR, name), 'utf8')));
}

/** The text of the two generated files, built in memory: { 'validators.generated.js': ..., '...d.ts': ... }. */
function generate() {
  const schemas = SCHEMAS.map(([, file]) => readSchema(file));
  const ajv = new Ajv2020({
    allErrors: true,
    strict: false,
    schemas,
    code: { source: true, formats: _`require("ajv-formats/dist/formats").fullFormats` },
  });
  addFormats(ajv);
  const exportsMap = {};
  SCHEMAS.forEach(([exportName], i) => {
    exportsMap[exportName] = schemas[i].$id;
  });
  const banner = '// Generated by scripts/build-validators.js (ML-27/ML-28). Do not edit; run `npm run engine:validators`.\n';
  return {
    'validators.generated.js': banner + normalizeText(standaloneCode(ajv, exportsMap)).replace(/\n*$/, '\n'),
    'validators.generated.d.ts': DECLARATIONS,
  };
}

function findStale(outDir) {
  const built = generate();
  const stale = [];
  for (const name of Object.keys(built)) {
    const file = path.join(outDir, name);
    if (!fs.existsSync(file) || normalizeText(fs.readFileSync(file, 'utf8')) !== built[name]) {
      stale.push(name);
    }
  }
  return stale;
}

function writeFiles(outDir) {
  const built = generate();
  fs.mkdirSync(outDir, { recursive: true });
  for (const name of Object.keys(built)) {
    fs.writeFileSync(path.join(outDir, name), built[name], { encoding: 'utf8' });
  }
  return Object.keys(built);
}

function main(argv) {
  const check = argv.includes('--check');
  if (argv.some((arg) => arg !== '--check')) {
    process.stderr.write('usage: node scripts/build-validators.js [--check]\n');
    return 2;
  }
  try {
    if (check) {
      const stale = findStale(OUT_DIR);
      if (stale.length > 0) {
        process.stdout.write('stale: ' + stale.join(', ') + '\n');
        process.stdout.write('run: npm run engine:validators\n');
        return 1;
      }
      process.stdout.write('up to date\n');
      return 0;
    }
    const names = writeFiles(OUT_DIR);
    process.stdout.write('wrote ' + names.length + ' files\n');
    return 0;
  } catch (error) {
    // A schema or JSON error message can quote file text, so only a fixed message is shown.
    process.stderr.write('error: the validators could not be built\n');
    return 2;
  }
}

module.exports = { generate, findStale, writeFiles, normalizeText };

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}
